<parameter name="content">import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (props: FallbackProps) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export interface FallbackProps {
  error: Error;
  errorInfo: ErrorInfo;
  retry: () => void;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({ errorInfo });

    console.error("[ErrorBoundary] Caught render error:", {
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
      timestamp: new Date().toISOString(),
    });

    this.props.onError?.(error, errorInfo);
  }

  retry = () => {
    this.setState({ error: null, errorInfo: null });
  };

  render() {
    const { error, errorInfo } = this.state;

    if (error && errorInfo) {
      if (this.props.fallback) {
        return this.props.fallback({ error, errorInfo, retry: this.retry });
      }
      return <DefaultFallback error={error} errorInfo={errorInfo} retry={this.retry} />;
    }

    return this.props.children;
  }
}

function DefaultFallback({ error, errorInfo, retry }: FallbackProps) {
  const [expanded, setExpanded] = React.useState(false);

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.message}>{error.message}</p>

        <button onClick={retry} style={styles.retryButton}>
          Try again
        </button>

        <button
          onClick={() => setExpanded((v) => !v)}
          style={styles.detailsToggle}
        >
          {expanded ? "Hide" : "Show"} details
        </button>

        {expanded && (
          <pre style={styles.stack}>
            {error.stack}
            {"\n\nComponent Stack:"}
            {errorInfo.componentStack}
          </pre>
        )}
      </div>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "100vh",
    padding: "1rem",
    backgroundColor: "#f9fafb",
    fontFamily: "system-ui, sans-serif",
  },
  card: {
    maxWidth: 560,
    width: "100%",
    padding: "2rem",
    borderRadius: 8,
    backgroundColor: "#fff",
    border: "1px solid #fee2e2",
    boxShadow: "0 1px 4px rgba(0,0,0,.08)",
  },
  heading: {
    margin: "0 0 .5rem",
    fontSize: "1.25rem",
    color: "#b91c1c",
  },
  message: {
    margin: "0 0 1.25rem",
    color: "#374151",
    wordBreak: "break-word",
  },
  retryButton: {
    marginRight: ".75rem",
    padding: ".5rem 1.25rem",
    borderRadius: 6,
    border: "none",
    backgroundColor: "#2563eb",
    color: "#fff",
    fontSize: ".875rem",
    cursor: "pointer",
  },
  detailsToggle: {
    padding: ".5rem 1rem",
    borderRadius: 6,
    border: "1px solid #d1d5db",
    backgroundColor: "transparent",
    color: "#374151",
    fontSize: ".875rem",
    cursor: "pointer",
  },
  stack: {
    marginTop: "1rem",
    padding: ".75rem",
    borderRadius: 6,
    backgroundColor: "#f3f4f6",
    fontSize: ".75rem",
    color: "#374151",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-all",
  },
};
