<invoke name="Write">
<parameter name="file_path">ErrorBoundary.example.tsx</parameter>
<parameter name="content">import React, { useState } from "react";
import { ErrorBoundary, FallbackProps } from "./ErrorBoundary";

// Component that throws on demand
function Bomb({ shouldThrow }: { shouldThrow: boolean }) {
  if (shouldThrow) throw new Error("Simulated render crash");
  return <p>Component rendered successfully.</p>;
}

// Example 1: default fallback UI
function DefaultFallbackExample() {
  const [shouldThrow, setShouldThrow] = useState(false);

  return (
    <ErrorBoundary onError={(err, info) => console.log("Parent notified:", err, info)}>
      <button onClick={() => setShouldThrow(true)}>Trigger error</button>
      <Bomb shouldThrow={shouldThrow} />
    </ErrorBoundary>
  );
}

// Example 2: custom fallback render prop
function CustomFallbackExample() {
  const [shouldThrow, setShouldThrow] = useState(false);

  const customFallback = ({ error, retry }: FallbackProps) => (
    <div style={{ padding: "1rem", border: "2px solid red", borderRadius: 8 }}>
      <strong>Custom UI:</strong> {error.message}
      <br />
      <button onClick={retry} style={{ marginTop: ".5rem" }}>
        Retry
      </button>
    </div>
  );

  return (
    <ErrorBoundary fallback={customFallback}>
      <button onClick={() => setShouldThrow(true)}>Trigger error</button>
      <Bomb shouldThrow={shouldThrow} />
    </ErrorBoundary>
  );
}

export default function App() {
  return (
    <div style={{ padding: "2rem", fontFamily: "system-ui, sans-serif" }}>
      <h1>ErrorBoundary demos</h1>
      <h2>1. Default fallback</h2>
      <DefaultFallbackExample />
      <h2>2. Custom fallback</h2>
      <CustomFallbackExample />
    </div>
  );
}
